sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading || newValue === '') {
        return;
    }

    var total = parseInt(g_form.getValue('quantity'), 10);
    var available = parseInt(newValue, 10);

    g_form.hideFieldMsg('available_quantity', true);

    if (isNaN(total) || isNaN(available)) {
        return;
    }

    if (available < 0 || available > total) {

        g_form.setValue('available_quantity', oldValue);

        g_form.showFieldMsg(
            'available_quantity',
            'Available Quantity must be between 0 and Total Quantity.',
            'error'
        );
    }
}
